package com.logatron.audit.application;
import com.logatron.audit.persistence.*;import com.logatron.auth.application.AuthenticatedUser;import jakarta.servlet.http.HttpServletRequest;import org.slf4j.MDC;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class AuditService{private final AuditEventRepository repository;public AuditService(AuditEventRepository repository){this.repository=repository;}@Transactional public void record(AuthenticatedUser actor,String action,String resourceType,UUID resourceId,UUID projectId,UUID environmentId,String outcome,HttpServletRequest request){record(actor,action,resourceType,resourceId,projectId,environmentId,outcome,Map.of(),request);}@Transactional public void record(AuthenticatedUser actor,String action,String resourceType,UUID resourceId,UUID projectId,UUID environmentId,String outcome,Map<String,String> metadata,HttpServletRequest request){repository.save(new AuditEventEntity(actor==null?null:actor.id(),actor==null?"anonymous":actor.subject(),action,resourceType,resourceId,projectId,environmentId,outcome,MDC.get("traceId"),clientIp(request),request==null?null:trim(request.getHeader("User-Agent"),500),metadata));}private String clientIp(HttpServletRequest r){return r==null?null:trim(r.getRemoteAddr(),45);}private String trim(String s,int n){return s==null?null:s.substring(0,Math.min(n,s.length()));}}
